#include <stdio.h>
/*
 * ex07：#SAT（模型计数）
 * 为什么：一个公式「有多少个赋值让它为真」直接决定它的信息量：
 *        模型越少，约束越强；模型数为 0 就是不可满足，为 2^n 就是重言式。
 * 本例对 f = (p∨q) ∧ (¬q∨r) ∧ (¬p∨¬r) 枚举 8 个赋值，逐个判定并计数。
 */
static int clause(int a, int b) { return a || b; }

int main(void) {
    printf("p q r | p v q | ~q v r | ~p v ~r | f\n");
    printf("------+-------+--------+---------+--\n");
    int cnt = 0;
    for (int v = 0; v < 8; v++) {
        int p = (v >> 2) & 1, q = (v >> 1) & 1, r = v & 1;
        int c1 = clause(p, q), c2 = clause(!q, r), c3 = clause(!p, !r);
        int f = c1 && c2 && c3;
        printf("%d %d %d |   %d   |   %d    |    %d    | %d%s\n", p, q, r, c1, c2, c3, f,
               f ? "  <- model" : "");
        cnt += f;
    }
    printf("\nmodels = %d out of 2^3 = 8\n", cnt);
    printf("interpretation: the formula pins down %d of the 3 bits' combinations.\n", cnt);
    printf("if models == 0 -> UNSAT;  if models == 8 -> TAUTOLOGY.\n");
    return 0;
}
